export type TweakSafety = "safe" | "aggressive" | "expert";
export type TweakImpact = "HIGH" | "MED" | "LOW";
export type TweakCategory =
    | "registry" | "network" | "fivem" | "nvidia" | "amd" | "intgpu"
    | "laptop" | "memory" | "fortnite" | "discord" | "debloat" | "wintitus"
    | "startup" | "processes" | "process-lasso" | "game-detection"
    | "rust" | "roblox" | "cod" | "spotify";

/**
 * Anti-cheat IDs that may appear in `TweakMeta.incompatibleWith`.
 * Kept in lock-step with `AntiCheatId` in `use-detected-anti-cheats.ts`.
 */
export type AntiCheatIdLiteral = "Vanguard" | "EAC" | "BattlEye" | "FACEIT";

export interface NativeAction {
    /** PowerShell snippet used by the current web "download .ps1" flow. */
    powershell?: string;
    /** Kind of native operation, used by the future Tauri exec engine. */
    type?: "registry" | "service" | "powerCfg" | "wmi" | "tool";
    /** Free-form params for the future Tauri exec engine. */
    params?: Record<string, unknown>;
}

export interface TweakMeta {
    id: string;
    category: TweakCategory;
    safety: TweakSafety;
    plainEnglish: string;       // <=140 chars
    verifiedOn: { win10: boolean; win11: boolean };
    // UI metadata (optional — populated for tweaks rendered from the registry)
    title?: string;
    description?: string;
    badge?: string;
    impact?: TweakImpact;
    warning?: string;
    recommended?: boolean;
    /** Anti-cheats that ban this tweak. TweakRow disables the toggle when one is detected. */
    incompatibleWith?: AntiCheatIdLiteral[];
    /** PS1 snippet + native exec descriptor (powers script-download today, Tauri later). */
    nativeAction?: NativeAction;
}

